<?php
declare(strict_types=1);
require_once __DIR__.'/../server/_core/Database.php';require_once __DIR__.'/../server/_core/CommerceOrders.php';require_once __DIR__.'/../server/_core/ReleaseAnnouncements.php';
use BYPCMS\Core\{Database,CommerceOrders,ReleaseAnnouncements};
$qa=realpath($argv[1]??'');if(!$qa)throw new RuntimeException('Explicit fixture required');$targets=json_decode(file_get_contents($qa.'/targets.json'),true);$root=$targets['platform']['root'];$config=require $root.'/_storage/config.php';
if($config['database']['host']!=='127.0.0.1'||$config['database']['port']!==3319||!str_starts_with($config['database']['name'],'bypcms_purchase_')||empty($config['app']['debug'])||($config['commerce']['test_smtp']['host']??'')!=='127.0.0.1'||($config['commerce']['test_smtp']['port']??0)!==8465)throw new RuntimeException('Own disposable loopback database and SMTP required');
$db=new Database($config);$orders=new CommerceOrders($db,$config,$root);$a=new ReleaseAnnouncements($db,$config,$root);$n=$orders->notifications;$checks=0;
function verify(bool $yes,string $why):void{global $checks;if(!$yes)throw new RuntimeException($why);$checks++;}
function control(string $mode):array{$c=curl_init('http://127.0.0.1:8049/control');curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode(['mail'=>$mode]),CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>5]);$out=curl_exec($c);curl_close($c);return json_decode($out,true);}
function row(int $id):array{global $db;return $db->one('SELECT * FROM byp_notification_outbox WHERE id=?',[$id]);}
$target=$db->one('SELECT c.id,c.email,o.id AS order_id,l.id AS license_id,l.license_key_hash,l.entitlements,l.status,l.installed_version FROM byp_customer_accounts c JOIN byp_customer_orders o ON o.customer_id=c.id JOIN byp_license_order_links k ON k.order_id=o.id JOIN byp_license_registry l ON l.id=k.license_id WHERE c.email LIKE "journey-content-%@example.test" LIMIT 1');if(!$target)throw new RuntimeException('Own synthetic purchase required');$id=(int)$target['id'];
$original=$orders->settings->get();$before=$db->one('SELECT COUNT(*) n,SUM(amount_minor) amount FROM byp_commerce_orders');$owner=(int)$db->one('SELECT u.id FROM byp_users u JOIN byp_roles r ON r.id=u.role_id WHERE r.slug="owner" LIMIT 1')['id'];$op=fn()=>bin2hex(random_bytes(16));
try{
    $a->subscribe($id,false);verify(!$a->subscribed($id)&&$a->queue($n)===0,'no email before separate opt-in');
    $db->execute('UPDATE byp_license_registry SET installed_version="2.7.2",status="active" WHERE id=?',[$target['license_id']]);
    $a->subscribe($id,true);verify($a->queue($n)===1,'one compatible release email queued');verify($a->queue($n)===0,'repeated worker cycle creates no duplicate');
    $mail=$db->one('SELECT o.* FROM byp_notification_outbox o JOIN byp_release_announcements a ON a.mail_id=o.id WHERE a.customer_id=? ORDER BY o.id DESC LIMIT 1',[$id]);$mailId=(int)$mail['id'];
    $detail=$n->detail($mailId);verify($detail['template_key']==='release_available'&&str_contains($detail['html'],'2.7.3')&&!str_contains($detail['message'],'BYP-'),'versioned plain/HTML template without licence key');
    $orders->settings->save(array_replace($original,['smtp_enabled'=>false]),$db);verify(!empty($n->process(1,$mailId)['disabled'])&&row($mailId)['state']==='pending','disabled SMTP preserves queued notification');
    $orders->settings->save(array_replace($original,['smtp_enabled'=>true,'smtp_host'=>'qa.invalid','smtp_port'=>465,'smtp_security'=>'ssl','smtp_user'=>'qa','smtp_password'=>'qa-only','from_email'=>'sender@example.test','from_name'=>'BYPCMS Release QA']),$db);
    control('accept');$result=$n->process(1,$mailId);verify($result['accepted']===1&&row($mailId)['state']==='accepted','actual TLS SMTP accepts release email');
    $operation=$op();$copy=$n->change($mailId,'resend',$owner,['operation_id'=>$operation,'confirmed'=>true]);verify($copy!==$mailId&&$n->change($mailId,'resend',$owner,['operation_id'=>$operation,'confirmed'=>true])===$copy,'confirmed resend retry creates exactly one copy');
    verify($n->detail($copy)['parent_id']===$mailId||$n->detail($copy)['parent_id']==(string)$mailId,'resend keeps parent and release subscription mapping');
    control('temporary');$n->process(1,$copy);verify(row($copy)['state']==='retry','temporary SMTP failure is retryable');$db->execute('UPDATE byp_notification_outbox SET next_attempt_at=NOW() WHERE id=?',[$copy]);control('accept');$n->process(1,$copy);verify(row($copy)['state']==='accepted','scheduled retry succeeds');
    $uncertain=$n->change($mailId,'resend',$owner,['operation_id'=>$op(),'confirmed'=>true]);control('drop');$n->process(1,$uncertain);verify(row($uncertain)['state']==='uncertain','disconnect after DATA remains uncertain');$attempts=row($uncertain)['attempts'];$n->process(1,$uncertain);verify(row($uncertain)['attempts']===$attempts,'uncertain delivery is not automatically duplicated');
    try{$n->change($uncertain,'retry',$owner,['operation_id'=>$op()]);throw new LogicException('Expected acknowledgement');}catch(RuntimeException $e){verify(!$e instanceof LogicException,'uncertain retry requires acknowledgement');}
    control('accept');$n->change($uncertain,'retry',$owner,['operation_id'=>$op(),'acknowledge'=>true]);$n->process(1,$uncertain);verify(row($uncertain)['state']==='accepted','acknowledged retry succeeds');
    $reject=$n->change($mailId,'resend',$owner,['operation_id'=>$op(),'confirmed'=>true]);control('reject');$n->process(1,$reject);verify(row($reject)['state']==='failed','permanent SMTP refusal remains failed');$attempts=row($reject)['attempts'];$n->process(1,$reject);verify(row($reject)['attempts']===$attempts,'permanent failure is not blindly retried');control('accept');$n->change($reject,'retry',$owner,['operation_id'=>$op()]);$n->process(1,$reject);verify(row($reject)['state']==='accepted','owner can retry after correcting delivery');
    $canceled=$n->change($mailId,'resend',$owner,['operation_id'=>$op(),'confirmed'=>true]);$a->subscribe($id,false);$n->process(1,$canceled);verify(row($canceled)['state']==='superseded','unsubscribe suppresses pending and resend mail');
    try{$n->change($mailId,'resend',$owner,['operation_id'=>$op(),'confirmed'=>true]);throw new LogicException('Expected unsubscribed refusal');}catch(RuntimeException $e){verify(!$e instanceof LogicException,'owner cannot bypass unsubscribe');}
    $a->subscribe($id,true);$blocked=$n->change($mailId,'resend',$owner,['operation_id'=>$op(),'confirmed'=>true]);$db->execute('UPDATE byp_license_registry SET status="suspended" WHERE id=?',[$target['license_id']]);$n->process(1,$blocked);verify(row($blocked)['state']==='superseded','suspended licence suppresses queued mail');
    $db->execute('UPDATE byp_license_registry SET status="active" WHERE id=?',[$target['license_id']]);$installed=$n->change($mailId,'resend',$owner,['operation_id'=>$op(),'confirmed'=>true]);$db->execute('UPDATE byp_license_registry SET installed_version="2.7.3" WHERE id=?',[$target['license_id']]);$n->process(1,$installed);verify(row($installed)['state']==='superseded','already installed version suppresses stale email');
    $after=$db->one('SELECT COUNT(*) n,SUM(amount_minor) amount FROM byp_commerce_orders');verify($before===$after,'notifications create no orders or payments');$license=$db->one('SELECT license_key_hash,entitlements FROM byp_license_registry WHERE id=?',[$target['license_id']]);verify($license['license_key_hash']===$target['license_key_hash']&&$license['entitlements']===$target['entitlements'],'notifications preserve licence key and entitlements');
    file_put_contents($qa.'/mail-result.json',json_encode(['checks'=>$checks,'tlsSink'=>true,'realPayments'=>0,'realEmails'=>0],JSON_PRETTY_PRINT));echo $checks." subscription, template, actual TLS SMTP, failures, resend, unsubscribe and licence preservation checks passed\n";
}finally{$a->subscribe($id,false);$db->execute('UPDATE byp_license_registry SET status=?,installed_version=? WHERE id=?',[$target['status'],$target['installed_version'],$target['license_id']]);$orders->settings->save($original,$db);control('accept');}
